type KnowledgeServiceHTTPClient interface {
	// AddLink AddLink 给文档添加与运维对象（CI / 模型 / 告警规则 / 预案 / 工单 / 作业 / 流程）的关联。
	AddLink(ctx context.Context, req *AddLinkRequest, opts ...http.CallOption) (rsp *AddLinkResponse, err error)
	// ArchiveDocument ArchiveDocument 归档文档：同步从索引移除，不再被检索。
	ArchiveDocument(ctx context.Context, req *ArchiveDocumentRequest, opts ...http.CallOption) (rsp *ArchiveDocumentResponse, err error)
	// ConfirmDocumentReview ConfirmDocumentReview 确认文档仍然有效：复审日期顺延一个周期，不产生版本。
	ConfirmDocumentReview(ctx context.Context, req *ConfirmDocumentReviewRequest, opts ...http.CallOption) (rsp *ConfirmDocumentReviewResponse, err error)
	// CreateDocument CreateDocument 新建知识文档草稿（Markdown 正文；需对空间的写权限）。
	CreateDocument(ctx context.Context, req *CreateDocumentRequest, opts ...http.CallOption) (rsp *CreateDocumentResponse, err error)
	// DeleteDocument DeleteDocument 删除文档（软删，同步移除索引）。
	DeleteDocument(ctx context.Context, req *DeleteDocumentRequest, opts ...http.CallOption) (rsp *DeleteDocumentResponse, err error)
	// GetDocument GetDocument 查询知识文档正文：可按标题路径只取其中一节（heading_path），避免整篇过长。
	GetDocument(ctx context.Context, req *GetDocumentRequest, opts ...http.CallOption) (rsp *GetDocumentResponse, err error)
	// GetOverview GetOverview 知识库首页概览：最近更新、我负责的、待我审核、待复审。
	GetOverview(ctx context.Context, req *GetOverviewRequest, opts ...http.CallOption) (rsp *GetOverviewResponse, err error)
	// GetVersion GetVersion 查询某个版本的正文快照。
	GetVersion(ctx context.Context, req *GetVersionRequest, opts ...http.CallOption) (rsp *GetVersionResponse, err error)
	// ListDocuments ListDocuments 分页查询文档（按空间 / 状态 / 标签 / 负责人 / 关键字筛选）。
	ListDocuments(ctx context.Context, req *ListDocumentsRequest, opts ...http.CallOption) (rsp *ListDocumentsResponse, err error)
	// ListRelated ListRelated 查询与某个运维对象相关的知识文档：显式关联 + 按对象描述语义检索，供他域页面侧栏使用。
	ListRelated(ctx context.Context, req *ListRelatedRequest, opts ...http.CallOption) (rsp *ListRelatedResponse, err error)
	// ListVersions ListVersions 查询文档的发布版本列表。
	ListVersions(ctx context.Context, req *ListVersionsRequest, opts ...http.CallOption) (rsp *ListVersionsResponse, err error)
	// PublishDocument PublishDocument 发布文档：生成新版本并重建索引；空间要求审核时转为提交审核。
	PublishDocument(ctx context.Context, req *PublishDocumentRequest, opts ...http.CallOption) (rsp *PublishDocumentResponse, err error)
	// RemoveLink RemoveLink 移除文档的一条关联。
	RemoveLink(ctx context.Context, req *RemoveLinkRequest, opts ...http.CallOption) (rsp *RemoveLinkResponse, err error)
	// RestoreDocument RestoreDocument 恢复已归档文档为已发布并重建索引。
	RestoreDocument(ctx context.Context, req *RestoreDocumentRequest, opts ...http.CallOption) (rsp *RestoreDocumentResponse, err error)
	// ReviewDocument ReviewDocument 审核待发布的文档：通过即发布，驳回退回草稿（需管理权限）。
	ReviewDocument(ctx context.Context, req *ReviewDocumentRequest, opts ...http.CallOption) (rsp *ReviewDocumentResponse, err error)
	// RollbackDocument RollbackDocument 以某个历史版本的正文发布新版本。
	RollbackDocument(ctx context.Context, req *RollbackDocumentRequest, opts ...http.CallOption) (rsp *RollbackDocumentResponse, err error)
	// Search Search 检索知识库：运维手册、规范、排查经验、历史故障复盘（全文 + 向量混合检索，只返回当前用户可见的内容）。
	Search(ctx context.Context, req *SearchRequest, opts ...http.CallOption) (rsp *SearchResponse, err error)
	// SubmitSearchFeedback SubmitSearchFeedback 对一次检索结果反馈有用 / 没用（仅本人的检索记录）。
	SubmitSearchFeedback(ctx context.Context, req *SubmitSearchFeedbackRequest, opts ...http.CallOption) (rsp *SubmitSearchFeedbackResponse, err error)
	// UpdateDocument UpdateDocument 保存文档草稿（标题 / 正文 / 标签 / 负责人 / 复审时间）；已发布文档的修改只改草稿，发布后才生效。
	UpdateDocument(ctx context.Context, req *UpdateDocumentRequest, opts ...http.CallOption) (rsp *UpdateDocumentResponse, err error)
}

